/**
 * @file The markers the theme editor writes at the top of the files it
 * generates, in one place for the editor and for doctor.
 *
 * @position api/theme-edit — internal
 */

/** The first words of a generated settings module the editor writes. */
export const EDITOR_GENERATED_MARK =
  'Generated by `astryx experimental theme editor';

/**
 * The words on every file of a theme's app copy (src/themes/<theme>/): the
 * start of "Written by `<the command that writes it>`", which a reader takes
 * whole. A copy written before the command was named carries the group's
 * words alone; both begin so.
 */
export const APP_COPY_MARK = 'Written by `astryx experimental theme editor';

/**
 * The mark an app copy's files carry, naming the command that writes them.
 * @param {string} slug
 */
export const appCopyMark = slug =>
  `Written by \`astryx experimental theme editor show ${slug}\``;

/**
 * The marks a file's leading comment can carry, and the command it names:
 * `kind` is `build` for a theme build's output, `editor` for a file the theme
 * editor writes (its settings module or app copy); `command` is the words in
 * backquotes after "Written by" or "Generated by" (for a build, the build
 * command). Null for a file without one. One reader for every caller.
 * @param {string} source the start of the file
 * @param {string} buildMarker the theme build's own marker
 * @returns {{kind: 'build' | 'editor', command: string} | null}
 */
export function generatedMark(source, buildMarker) {
  const leading =
    /^\s*(?:\/\*[\s\S]*?\*\/|(?:\/\/[^\n]*(?:\n|$)\s*)+)/.exec(source)?.[0] ??
    '';
  if (leading.includes(buildMarker))
    return {kind: 'build', command: 'astryx theme build'};
  if (![APP_COPY_MARK, EDITOR_GENERATED_MARK].some(m => leading.includes(m)))
    return null;
  return {
    kind: 'editor',
    command:
      /(?:Written|Generated) by `([^`]+)`/.exec(leading)?.[1] ??
      'the command that made it',
  };
}
